function graduationDraft(id='graduation-2026'){const memories=[{id:'grad-first-day',kind:'note',title:'The first day',date:'September 2022',source:'Demo memory',body:'A new campus, a very full backpack, and no idea where the lecture hall was.'},{id:'grad-late-nights',kind:'message',title:'One more deadline',date:'April 2026',source:'Demo message from Jo',body:'submitted. finally. coffee tomorrow?'},{id:'grad-finish',kind:'note',title:'You did it',date:'October 2026',source:'Demo memory',body:'All those late nights led here. So proud to see you graduate.'}];return {id,cover:'blue',snapshot:{...structuredClone(defaults),draftId:id,person:'Jo',occasion:'Graduation',date:'2026-10-30',format:'storybook',title:'Graduation 2026',authoredTitle:true,memories,selected:memories.map(m=>m.id),notes:{},note:'Here’s to everything you worked for, and everything that comes next. So proud of you, Jo.',lastStep:'editor'}};}
let draftLibrary;
try{draftLibrary=JSON.parse(localStorage.getItem('ribbon-library-v1')||'null');}catch{draftLibrary=null;}
if(!Array.isArray(draftLibrary)){
 draftLibrary=[{id:state.draftId,snapshot:structuredClone(state),cover:'plum'},graduationDraft()];
}
