if(birthdayDrafts.length>1){const duplicate=birthdayDrafts[1],index=draftLibrary.findIndex(d=>d.id===duplicate.id);draftLibrary[index]=graduationDraft(duplicate.id);if(state.draftId===duplicate.id){state=structuredClone(birthdayDrafts[0].snapshot);localStorage.setItem('ribbon-draft-v1',JSON.stringify(state));}localStorage.setItem('ribbon-library-v1',JSON.stringify(draftLibrary));}
function removeRepeatedSample(st){st.memories=st.memories.map(m=>m.image&&m.image.includes('assets/friendship.png')?{...m,kind:'note',image:'',source:'Demo memory'}:m);return st;}
removeRepeatedSample(state);draftLibrary.forEach(d=>removeRepeatedSample(d.snapshot));
let creation=null,datesExpanded=false;
