Instagram:'<rect x="3.5" y="3.5" width="17" height="17" rx="5" fill="none" stroke="white" stroke-width="1.8"/><circle cx="12" cy="12" r="4" fill="none" stroke="white" stroke-width="1.8"/><circle cx="17.4" cy="6.8" r="1.1"/>',
