Telegram:'<path d="m21.4 4.4-3.1 15c-.2 1.1-.9 1.3-1.8.8l-4.8-3.6-2.3 2.2c-.2.3-.5.5-.9.5l.4-4.9 8.9-8.1c.4-.3-.1-.5-.6-.2l-11 6.9-4.7-1.5c-1-.3-1-1 .2-1.5l18.3-7c.9-.3 1.7.2 1.4 1.4Z"/>',
